function deleteUser(userId) {
  // Verify user is authenticated
  if (!currentUser) {
    return 'Not authenticated';
  }

  // Verify user role from database, not from client
  let userRole = database.getUserRole(currentUser.id);
  if (userRole != 'admin') {
    logSecurityEvent('privilege_escalation_attempt', currentUser.id, 'delete_user');
    return 'Permission denied';
  }

  // Verify target user exists and can be deleted
  let targetUser = database.find(userId);
  if (!targetUser) {
    return 'User not found';
  }

  // Additional checks: can't delete yourself, can't delete other admins
  if (userId == currentUser.id) {
    return 'Cannot delete yourself';
  }
  if (targetUser.role == 'admin') {
    return 'Cannot delete admin users';
  }

  // Log the action for audit trail
  logAuditEvent('user_deleted', currentUser.id, userId, 'admin_action');

  // Finally, delete the user
  targetUser.delete();
  return 'User deleted';
}

